import React, { useState, useEffect, useRef } from 'react';
import io from 'socket.io-client';
import './SettingsDashboard.css';

export function SettingsDashboard() {
  const [notifications, setNotifications] = useState(true);
  const [sensitivity, setSensitivity] = useState(80);
  const [retention, setRetention] = useState(30);
  const socketRef = useRef(null);
  const [synced, setSynced] = useState(false);

  useEffect(() => {
    socketRef.current = io('http://localhost:5000', {
        transports: ['websocket', 'polling']
    });

    socketRef.current.on('connect', () => {
        console.log("Settings connected");
    });

    socketRef.current.on('connected', (data) => {
        if (data.settings) {
            setSensitivity(data.settings.sensitivity);
            setRetention(data.settings.retention);
            setNotifications(data.settings.notifications);
            setSynced(true);
        }
    });

    socketRef.current.on('settings_updated', (newSettings) => {
        setSensitivity(newSettings.sensitivity);
        setRetention(newSettings.retention);
        setNotifications(newSettings.notifications);
    });

    return () => {
        if (socketRef.current) socketRef.current.disconnect();
    };
  }, []);

  const updateSetting = (key, value) => {
      // Optimistic update
      if (key === 'sensitivity') setSensitivity(value);
      if (key === 'retention') setRetention(value);
      if (key === 'notifications') setNotifications(value);

      // Emit to server
      if (socketRef.current) {
          socketRef.current.emit('update_settings', { [key]: value });
      }
  };

  return (
    <div className="settings-container">
      <div className="settings-header">
        <h2>⚙ System Configuration {synced && <span style={{fontSize:'0.8rem', color:'#00ff88', marginLeft:'10px'}}>● Live Synced</span>}</h2>
        <p>Manage global parameters and user preferences</p>
      </div>

